/**
 * Calls listener(tasks) after every change. It is not called with the
 * current list, so a caller that needs it renders once when it starts.
 * @param {(tasks: readonly Task[]) => void} listener
 * @returns {() => void} a function that stops the calls
 */
subscribe(listener) {
  this.#listeners.add(listener);
  return () => {
    this.#listeners.delete(listener);
  };
}

#update(id, change) {
  let changed = false;
  const next = this.#tasks.map((task) => {
    if (task.id !== id) return task;
    const updated = change(task);
    if (updated !== task) changed = true;
    return updated;
  });
  if (changed) this.#commit(next);
  return changed;
}

#commitRemoval(next) {
  if (next.length === this.#tasks.length) return false;
  this.#commit(next);
  return true;
}

#commit(next) {
  this.#tasks = freeze(next);
  for (const listener of this.#listeners) listener(this.#tasks);
}

describe("subscribe", () => {
  it("calls listeners with the new list after each change", () => {
    const store = createStore([milk]);
    const listener = vi.fn();
    store.subscribe(listener);
    store.toggle("a");
    store.add("Call Ada");
    expect(listener).toHaveBeenCalledTimes(2);
    expect(listener).toHaveBeenLastCalledWith(store.tasks);
  });

  it("stays quiet when nothing changed", () => {
    const store = createStore([milk]);
    const listener = vi.fn();
    store.subscribe(listener);
    store.add("  ");
    store.remove("nope");
    store.rename("a", "Buy milk");
    store.clearCompleted();
    expect(listener).not.toHaveBeenCalled();
  });

  it("stops calling a listener after it unsubscribes", () => {
    const store = createStore([milk]);
    const listener = vi.fn();
    const unsubscribe = store.subscribe(listener);
    unsubscribe();
    store.toggle("a");
    expect(listener).not.toHaveBeenCalled();
  });
});

// The composition root: the one place that creates the store, finds the page's
// elements, and connects them. Every other module gets what it needs passed
// in, which keeps each one small and testable on its own.

import { filterFromSearch, TaskController } from "./controller/task-controller.js";
import { qs } from "./lib/dom.js";
import { loadTasks, saveTasks } from "./model/persist.js";
import { SEED_TASKS } from "./model/seed.js";
import { TaskStore } from "./model/task-store.js";

const store = new TaskStore(loadTasks() ?? SEED_TASKS);
store.subscribe((tasks) => saveTasks(tasks));

const controller = new TaskController(store, {
  form: qs("#new-task"),
  list: qs("#task-list"),
  footer: qs("#task-footer"),
});
controller.start(filterFromSearch(location.search));

#onSubmit(event) {
  event.preventDefault();
  const input = this.#titleInput;
  if (this.#store.add(input.value)) input.value = "";
  input.focus();
}

#onAction(control) {
  const { row, id, index } = rowOf(control);
  switch (control.dataset.action) {
    case "toggle":
      this.#store.toggle(id);
      // Under the Active or Completed filter the row may have just left the list.
      this.#focus(id, index, "toggle");
      break;
    case "edit":
      this.#edit(row);
      break;
    case "delete":
      this.#store.remove(id);
      this.#focus(id, index, "toggle");
      break;
  }
}

// Intl.PluralRules knows each language's plural forms. English needs two
// ("1 item", "2 items"), but other languages need up to six.
const pluralRules = new Intl.PluralRules("en-US");
const NOUNS = { one: "item", other: "items" };

/** "1 item left", "0 items left", "3 items left". */
export function itemsLeftText(count) {
  const noun = NOUNS[pluralRules.select(count)] ?? NOUNS.other;
  return `${count} ${noun} left`;
}

export function renderFooter(footer, tasks, filter) {
  footer.hidden = tasks.length === 0;
  qs(".task-count", footer).textContent = itemsLeftText(countActive(tasks));

  for (const link of qsa("a[data-filter]", footer)) {
    if (link.dataset.filter === filter) link.setAttribute("aria-current", "page");
    else link.removeAttribute("aria-current");
  }

  qs("#clear-completed", footer).hidden = !tasks.some((task) => task.done);
}

