function isTask(value) {
  return (
    typeof value === "object" &&
    value !== null &&
    typeof value.id === "string" &&
    typeof value.title === "string" &&
    typeof value.done === "boolean"
  );
}

/** Keeps only the fields a task has, so stray properties are never saved or loaded. */
function pick({ id, title, done }) {
  return { id, title, done };
}

/** The filter named in a query string such as "?filter=active", or "all". */
export function filterFromSearch(search) {
  const filter = new URLSearchParams(search).get("filter");
  return isFilter(filter) ? filter : "all";
}
